  {"claim": "The access occurred on D0028, a workstation in PCP, the user's own clinic.", "sources": ["L1", "L2", "L3", "G5"]},
  {"claim": "P02841 has no encounter in the period, so the facts show no documented care purpose for this access.", "sources": ["G3"]},
  {"claim": "U0192 accessed many other patients the same morning, a pattern consistent with clinic work, but it does not establish a purpose for the P02841 access.", "sources": ["L4", "L13", "L22", "L29", "L33"]}
 ],
 "risk_indicators": [
  {"claim": "An identity-graph connection of type 'proximity' links U0192 and P02841; the facts do not specify its nature.", "sources": ["G4"]},
  {"claim": "The accessed patient has no encounter in the period, so the access lacks any documented job-related reason.", "sources": ["G3", "L1", "L2", "L3"]}
 ],
 "missing_information": [
  "The nature of the 'proximity' connection (G4): family, neighbor, acquaintance, or other.",
  "Whether any care-related reason existed that is not recorded as an encounter (e.g., phone contact or result review), since G3 only rules out an encounter.",
